import { Controller, Get, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

const ROLE = '예산·회계 담당자';
// 가정: 기간 마감 테이블이 없으므로 전표 상태가 '마감'이면 마감된 기간의 전표로 본다.
const CLOSED_STATUS = '마감';
const APPROVED_STATUS = '승인';
const CANCELED_STATUS = '승인 취소';

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function parseId(value: unknown, label: string): string {
  const text = typeof value === 'number' ? String(value) : value;
  if (typeof text !== 'string' || !/^[0-9]+$/.test(text)) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

function optId(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return parseId(value, label);
}

function optText(value: unknown, max: number, label: string): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하의 글자여야 합니다.');
  }
  return value;
}

function optAmount(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const n = typeof value === 'number' ? value : typeof value === 'string' && value.trim() !== '' ? Number(value) : NaN;
  if (!Number.isFinite(n) || n < 0) {
    throw invalid(label + '은(는) 0 이상의 숫자여야 합니다.');
  }
  return String(n);
}

async function loadEntry(db: Db, id: string, lock: boolean): Promise<Record<string, any>> {
  const sql =
    'SELECT journal_entry_id AS "journalEntryId", to_char(entry_date, \'YYYY-MM-DD\') AS "entryDate", status, ' +
    'total_debit_amount AS "totalDebitAmount", total_credit_amount AS "totalCreditAmount", ' +
    'summary, evidence_detail AS "evidenceDetail" ' +
    'FROM journal_entry WHERE journal_entry_id = CAST(:id AS bigint)' +
    (lock ? ' FOR UPDATE' : '');
  const rows = await db.query(sql, { id });
  if (rows.length === 0) {
    throw new ApiError(404, 'JOURNAL_ENTRY_NOT_FOUND', '전표를 찾을 수 없습니다.');
  }
  return rows[0];
}

async function loadLines(db: Db, id: string): Promise<Record<string, any>[]> {
  return db.query(
    'SELECT journal_entry_line_id AS "journalEntryLineId", journal_entry_id AS "journalEntryId", ' +
      'account_subject_id AS "accountSubjectId", partner_id AS "partnerId", project_id AS "projectId", ' +
      'budget_account_id AS "budgetAccountId", line_no AS "lineNo", debit_amount AS "debitAmount", ' +
      'credit_amount AS "creditAmount", management_item_value AS "managementItemValue", summary ' +
      'FROM journal_entry_line WHERE journal_entry_id = CAST(:id AS bigint) ORDER BY line_no',
    { id },
  );
}

async function writeHistory(
  db: Db,
  userId: string,
  id: string,
  changeType: string,
  content: string,
  reason: string | null,
): Promise<void> {
  await db.execute(
    'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, change_reason, created_at, updated_at) ' +
      'VALUES (CAST(:userId AS bigint), \'journal_entry\', CAST(:id AS bigint), :changeType, now(), :content, CAST(:reason AS varchar), now(), now())',
    { userId, id, changeType, content, reason },
  );
}

async function requireRef(db: Db, sql: string, id: string | null, message: string): Promise<void> {
  if (id === null) {
    return;
  }
  const rows = await db.query(sql, { id });
  if (rows.length === 0) {
    throw invalid(message);
  }
}

function guardEditable(status: string): void {
  if (status === CLOSED_STATUS) {
    throw new ApiError(409, 'JOURNAL_PERIOD_CLOSED', '마감된 기간의 전표는 마감 취소 전에는 수정할 수 없습니다.');
  }
  if (status === APPROVED_STATUS) {
    throw new ApiError(409, 'JOURNAL_ENTRY_APPROVED', '승인된 전표는 승인 해제 후에 수정할 수 있습니다.');
  }
}

@Controller('api/v1')
export class FnSfr00801Controller {
  @Patch('/journal-entries/evidence-details')
  async updateJournalEntryEvidenceDetails(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const rawIds = data['journalEntryIds'];
    if (!Array.isArray(rawIds) || rawIds.length === 0) {
      throw new ApiError(422, 'JOURNAL_ENTRY_NOT_SELECTED', '변경할 전표를 선택하세요.');
    }
    const ids = Array.from(new Set(rawIds.map((v) => parseId(v, '전표 ID'))));
    const evidence = data['evidenceDetail'];
    if (typeof evidence !== 'string' || evidence.trim() === '' || evidence.length > 1000) {
      throw invalid('증빙내역은 1000자 이하로 입력해야 합니다.');
    }
    return transaction(async (db) => {
      const found: Record<string, Record<string, any>> = {};
      for (const id of ids) {
        const rows = await db.query(
          'SELECT status FROM journal_entry WHERE journal_entry_id = CAST(:id AS bigint) FOR UPDATE',
          { id },
        );
        if (rows.length > 0) {
          found[id] = rows[0];
          if (rows[0].status === CLOSED_STATUS) {
            throw new ApiError(409, 'JOURNAL_PERIOD_CLOSED', '마감된 기간의 전표가 포함되어 있습니다.');
          }
        }
      }
      const results: Record<string, unknown>[] = [];
      for (const id of ids) {
        const row = found[id];
        if (!row) {
          results.push({ journalEntryId: Number(id), success: false, message: '전표를 찾을 수 없습니다.' });
          continue;
        }
        if (row.status === APPROVED_STATUS) {
          results.push({ journalEntryId: Number(id), success: false, message: '승인된 전표는 승인 해제 후에 수정할 수 있습니다.' });
          continue;
        }
        await db.execute(
          'UPDATE journal_entry SET evidence_detail = :evidence, updated_at = now() WHERE journal_entry_id = CAST(:id AS bigint)',
          { id, evidence },
        );
        await writeHistory(db, user.id, id, '일괄 변경', '증빙내역 일괄 변경', null);
        results.push({ journalEntryId: Number(id), success: true, message: '변경했습니다.' });
      }
      return { results };
    });
  }

  @Get('/journal-entries/:journalEntryId')
  async getJournalEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    checks.queryOf(req.query);
    const id = parseId(req.params['journalEntryId'], '전표 ID');
    return transaction(async (db) => {
      const entry = await loadEntry(db, id, false);
      const lines = await loadLines(db, id);
      return { ...entry, lines };
    });
  }

  @Patch('/journal-entries/:journalEntryId')
  async updateJournalEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const id = parseId(req.params['journalEntryId'], '전표 ID');
    const summary = optText(data['summary'], 500, '적요');
    const evidence = optText(data['evidenceDetail'], 1000, '증빙내역');
    const rawLines = data['lines'];
    if (rawLines !== undefined && rawLines !== null && !Array.isArray(rawLines)) {
      throw invalid('분개 라인 형식이 올바르지 않습니다.');
    }
    const lineInputs: Record<string, unknown>[] = [];
    for (const raw of (rawLines as unknown[] | undefined) ?? []) {
      if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
        throw invalid('분개 라인 형식이 올바르지 않습니다.');
      }
      lineInputs.push(raw as Record<string, unknown>);
    }
    if (summary === null && evidence === null && lineInputs.length === 0) {
      throw invalid('수정할 내용을 입력하세요.');
    }
    return transaction(async (db) => {
      const entry = await loadEntry(db, id, true);
      guardEditable(entry['status']);
      for (const input of lineInputs) {
        const lineId = parseId(input['journalEntryLineId'], '분개 라인 ID');
        const accountId = optId(input['accountSubjectId'], '계정과목');
        const partnerId = optId(input['partnerId'], '거래처');
        const projectId = optId(input['projectId'], '프로젝트');
        const budgetId = optId(input['budgetAccountId'], '예산과목');
        const debit = optAmount(input['debitAmount'], '차변 금액');
        const credit = optAmount(input['creditAmount'], '대변 금액');
        const mgmt = optText(input['managementItemValue'], 500, '관리항목 값');
        const lineSummary = optText(input['summary'], 500, '분개 적요');
        const own = await db.query(
          'SELECT journal_entry_line_id FROM journal_entry_line WHERE journal_entry_line_id = CAST(:lineId AS bigint) AND journal_entry_id = CAST(:id AS bigint)',
          { lineId, id },
        );
        if (own.length === 0) {
          throw invalid('이 전표에 속하지 않는 분개 라인입니다.');
        }
        await requireRef(db, 'SELECT account_subject_id FROM account_subject WHERE account_subject_id = CAST(:id AS bigint)', accountId, '존재하지 않는 계정과목입니다.');
        await requireRef(db, 'SELECT partner_id FROM partner WHERE partner_id = CAST(:id AS bigint)', partnerId, '존재하지 않는 거래처입니다.');
        await requireRef(db, 'SELECT project_id FROM project WHERE project_id = CAST(:id AS bigint)', projectId, '존재하지 않는 프로젝트입니다.');
        await requireRef(db, 'SELECT budget_account_id FROM budget_account WHERE budget_account_id = CAST(:id AS bigint)', budgetId, '존재하지 않는 예산과목입니다.');
        await db.execute(
          'UPDATE journal_entry_line SET ' +
            'account_subject_id = COALESCE(CAST(:accountId AS bigint), account_subject_id), ' +
            'partner_id = COALESCE(CAST(:partnerId AS bigint), partner_id), ' +
            'project_id = COALESCE(CAST(:projectId AS bigint), project_id), ' +
            'budget_account_id = COALESCE(CAST(:budgetId AS bigint), budget_account_id), ' +
            'debit_amount = COALESCE(CAST(:debit AS numeric), debit_amount), ' +
            'credit_amount = COALESCE(CAST(:credit AS numeric), credit_amount), ' +
            'management_item_value = COALESCE(CAST(:mgmt AS varchar), management_item_value), ' +
            'summary = COALESCE(CAST(:lineSummary AS varchar), summary), ' +
            'updated_at = now() ' +
            'WHERE journal_entry_line_id = CAST(:lineId AS bigint) AND journal_entry_id = CAST(:id AS bigint)',
          { accountId, partnerId, projectId, budgetId, debit, credit, mgmt, lineSummary, lineId, id },
        );
      }
      const sums = await db.query(
        'SELECT COALESCE(SUM(debit_amount), 0) AS "debit", COALESCE(SUM(credit_amount), 0) AS "credit" FROM journal_entry_line WHERE journal_entry_id = CAST(:id AS bigint)',
        { id },
      );
      const debitTotal = Number(sums[0].debit);
      const creditTotal = Number(sums[0].credit);
      if (debitTotal !== creditTotal) {
        throw new ApiError(422, 'JOURNAL_ENTRY_DEBIT_CREDIT_MISMATCH', '차변 합계와 대변 합계가 일치해야 저장할 수 있습니다.');
      }
      await db.execute(
        'UPDATE journal_entry SET summary = COALESCE(CAST(:summary AS varchar), summary), ' +
          'evidence_detail = COALESCE(CAST(:evidence AS varchar), evidence_detail), ' +
          'total_debit_amount = CAST(:debit AS numeric), total_credit_amount = CAST(:credit AS numeric), ' +
          'updated_at = now() WHERE journal_entry_id = CAST(:id AS bigint)',
        { summary, evidence, debit: String(debitTotal), credit: String(creditTotal), id },
      );
      const changed: string[] = [];
      if (summary !== null) {
        changed.push('적요');
      }
      if (evidence !== null) {
        changed.push('증빙내역');
      }
      if (lineInputs.length > 0) {
        changed.push('분개 라인 ' + lineInputs.length + '건');
      }
      await writeHistory(db, user.id, id, '수정', '전표 수정: ' + changed.join(', '), null);
      return { journalEntryId: Number(id), status: entry['status'] };
    });
  }

  @Post('/journal-entries/:journalEntryId/cancel-approval')
  @HttpCode(200)
  async cancelJournalEntryApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const id = parseId(req.params['journalEntryId'], '전표 ID');
    const reason = optText(data['changeReason'], 500, '변경 사유');
    return transaction(async (db) => {
      const entry = await loadEntry(db, id, true);
      if (entry['status'] === CLOSED_STATUS) {
        throw new ApiError(409, 'JOURNAL_PERIOD_CLOSED', '마감된 기간의 전표는 마감 취소 전에는 승인을 해제할 수 없습니다.');
      }
      if (entry['status'] !== APPROVED_STATUS) {
        throw new ApiError(409, 'JOURNAL_ENTRY_NOT_APPROVED', '승인된 전표만 승인을 해제할 수 있습니다.');
      }
      await db.execute(
        'UPDATE journal_entry SET status = :status, updated_at = now() WHERE journal_entry_id = CAST(:id AS bigint)',
        { status: CANCELED_STATUS, id },
      );
      // 가정: 변경 이력의 대상 유형·내용은 스펙의 가정 값을 따른다.
      await writeHistory(db, user.id, id, '승인 취소', '승인 → 승인 취소', reason);
      return { journalEntryId: Number(id), status: CANCELED_STATUS };
    });
  }

  @Get('/journal-entries/:journalEntryId/print')
  async printJournalEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    checks.queryOf(req.query);
    const id = parseId(req.params['journalEntryId'], '전표 ID');
    return transaction(async (db) => {
      const entry = await loadEntry(db, id, false);
      const lines = await db.query(
        'SELECT l.line_no AS "lineNo", s.code AS "accountCode", s.name AS "accountName", ' +
          'l.debit_amount AS "debitAmount", l.credit_amount AS "creditAmount", ' +
          'l.management_item_value AS "managementItemValue", l.summary AS "summary" ' +
          'FROM journal_entry_line l JOIN account_subject s ON s.account_subject_id = l.account_subject_id ' +
          'WHERE l.journal_entry_id = CAST(:id AS bigint) ORDER BY l.line_no',
        { id },
      );
      const out: string[] = [];
      out.push('전표 번호: ' + entry['journalEntryId']);
      out.push('전표 일자: ' + entry['entryDate']);
      out.push('전표 상태: ' + entry['status']);
      out.push('적요: ' + (entry['summary'] ?? ''));
      out.push('증빙내역: ' + (entry['evidenceDetail'] ?? ''));
      out.push('');
      for (const line of lines) {
        out.push(
          line.lineNo + '. [' + line.accountCode + '] ' + line.accountName +
            ' | 차변 ' + line.debitAmount + ' | 대변 ' + line.creditAmount +
            ' | 관리항목 ' + (line.managementItemValue ?? '') + ' | ' + (line.summary ?? ''),
        );
      }
      out.push('');
      out.push('차변 합계: ' + (entry['totalDebitAmount'] ?? 0));
      out.push('대변 합계: ' + (entry['totalCreditAmount'] ?? 0));
      return {
        journalEntryId: entry['journalEntryId'],
        entryDate: entry['entryDate'],
        printFile: out.join('\n'),
      };
    });
  }
}

