import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  Pairs,
  RefName,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

type Mode = '' | 'create' | 'bulk' | 'edit' | 'cancel';

function messageOf(e: unknown): string {
  return e instanceof Error ? e.message : '처리하지 못했습니다.';
}

function CreateForm({ role, onDone }: { role: string; onDone: (id: number) => Promise<void> }) {
  const [resolutionId, setResolutionId] = useState<number | string>('');
  const [accountId, setAccountId] = useState<number | string>('');
  const [summary, setSummary] = useState('');
  const [evidence, setEvidence] = useState('');
  return (
    <Form
      submit="전표 저장"
      onSubmit={async () => {
        if (resolutionId === '' || accountId === '') {
          throw new Error('결의서와 계정과목을 선택하세요.');
        }
        if (summary.length > 500 || evidence.length > 1000) {
          throw new Error('적요는 500자, 증빙내역은 1000자 이하로 입력하세요.');
        }
        const res = await call('POST', '/journal-entries', role, {
          expenseResolutionId: resolutionId,
          accountSubjectId: accountId,
          summary: summary || undefined,
          evidenceDetail: evidence || undefined,
        });
        await onDone(Number(res.journalEntryId));
      }}
    >
      <Field label="결의서 ID" required wide>
        <LookupSelect table="expense_resolution" role={role} value={resolutionId} onChange={setResolutionId} />
      </Field>
      <Field label="분개에 사용할 계정과목 ID" required wide>
        <LookupSelect table="account_subject" role={role} value={accountId} onChange={setAccountId} />
      </Field>
      <Field label="적요" wide>
        <TextInput value={summary} onChange={setSummary} />
      </Field>
      <Field label="증빙내역" wide>
        <TextInput value={evidence} onChange={setEvidence} multiline />
      </Field>
    </Form>
  );
}

function BulkForm({
  role,
  notify,
  onDone,
}: {
  role: string;
  notify: (text: string) => void;
  onDone: (ids: number[]) => Promise<void>;
}) {
  const [ids, setIds] = useState<number[]>([]);
  const [pick, setPick] = useState<number | string>('');
  const [evidence, setEvidence] = useState('');
  return (
    <Form
      submit="증빙내역 일괄 변경"
      note="선택한 전표에만 적용되며, 승인된 전표는 승인 해제 후에 변경할 수 있습니다."
      onSubmit={async () => {
        if (ids.length === 0) {
          throw new Error('변경할 전표를 선택하세요.');
        }
        if (evidence.trim() === '' || evidence.length > 1000) {
          throw new Error('증빙내역은 1000자 이하로 입력하세요.');
        }
        const res = await call('PATCH', '/journal-entries/evidence-details', role, {
          journalEntryIds: ids,
          evidenceDetail: evidence,
        });
        const results = (res.results as Row[]) ?? [];
        const failed = results.filter((r) => r.success !== true);
        if (failed.length > 0) {
          notify('일부 전표는 변경하지 못했습니다: ' + failed.map((r) => String(r.journalEntryId) + ' ' + String(r.message)).join(', '));
        }
        await onDone(ids);
      }}
    >
      <Field label="변경 대상 전표 ID" required wide hint="전표를 고른 뒤 추가를 누르세요.">
        <LookupSelect table="journal_entry" role={role} value={pick} onChange={setPick} />
      </Field>
      <button
        type="button"
        className="ghost"
        onClick={() => {
          if (pick !== '' && !ids.includes(Number(pick))) {
            setIds([...ids, Number(pick)]);
          }
          setPick('');
        }}
      >
        전표 추가
      </button>
      {ids.map((id) => (
        <div key={id}>
          <RefName table="journal_entry" role={role} value={id} />
          <button type="button" className="ghost" onClick={() => setIds(ids.filter((v) => v !== id))}>
            빼기
          </button>
        </div>
      ))}
      <Field label="증빙내역" required wide>
        <TextInput value={evidence} onChange={setEvidence} multiline />
      </Field>
    </Form>
  );
}

function EditForm({ role, detail, onDone }: { role: string; detail: Row; onDone: () => Promise<void> }) {
  const [summary, setSummary] = useState(String(detail.summary ?? ''));
  const [evidence, setEvidence] = useState(String(detail.evidenceDetail ?? ''));
  const [lines, setLines] = useState<Row[]>(
    ((detail.lines as Row[]) ?? []).map((l) => ({
      journalEntryLineId: l.journalEntryLineId,
      partnerId: l.partnerId ?? '',
      projectId: l.projectId ?? '',
      budgetAccountId: l.budgetAccountId ?? '',
      managementItemValue: l.managementItemValue ?? '',
      summary: l.summary ?? '',
    })),
  );
  const setLine = (index: number, key: string, value: unknown) => {
    setLines(lines.map((l, i) => (i === index ? { ...l, [key]: value } : l)));
  };
  return (
    <Form
      submit="수정 저장"
      onSubmit={async () => {
        if (summary.length > 500 || evidence.length > 1000) {
          throw new Error('적요는 500자, 증빙내역은 1000자 이하로 입력하세요.');
        }
        await call('PATCH', `/journal-entries/${detail.journalEntryId}`, role, {
          summary,
          evidenceDetail: evidence,
          lines,
        });
        await onDone();
      }}
    >
      <Field label="적요" wide>
        <TextInput value={summary} onChange={setSummary} />
      </Field>
      <Field label="증빙내역" wide>
        <TextInput value={evidence} onChange={setEvidence} multiline />
      </Field>
      {lines.map((line, i) => (
        <div key={String(line.journalEntryLineId)}>
          <h3>분개 라인 {i + 1}</h3>
          <Field label="거래처 ID" wide>
            <LookupSelect table="partner" role={role} value={line.partnerId} onChange={(v) => setLine(i, 'partnerId', v)} />
          </Field>
          <Field label="프로젝트 ID" wide>
            <LookupSelect table="project" role={role} value={line.projectId} onChange={(v) => setLine(i, 'projectId', v)} />
          </Field>
          <Field label="예산과목 ID" wide>
            <LookupSelect table="budget_account" role={role} value={line.budgetAccountId} onChange={(v) => setLine(i, 'budgetAccountId', v)} />
          </Field>
          <Field label="관리항목 값" wide>
            <TextInput value={line.managementItemValue} onChange={(v) => setLine(i, 'managementItemValue', v)} />
          </Field>
          <Field label="적요" wide>
            <TextInput value={line.summary} onChange={(v) => setLine(i, 'summary', v)} />
          </Field>
        </div>
      ))}
    </Form>
  );
}

function CancelForm({ role, detail, onDone }: { role: string; detail: Row; onDone: () => Promise<void> }) {
  const [reason, setReason] = useState('');
  return (
    <Form
      submit="승인 해제"
      danger
      note="승인을 해제하면 전표 상태가 승인 취소로 바뀌고 변경 이력이 남습니다."
      onSubmit={async () => {
        if (reason.length > 500) {
          throw new Error('변경 사유는 500자 이하로 입력하세요.');
        }
        await call('POST', `/journal-entries/${detail.journalEntryId}/cancel-approval`, role, {
          changeReason: reason || undefined,
        });
        await onDone();
      }}
    >
      <Field label="변경 사유" wide>
        <TextInput value={reason} onChange={setReason} multiline />
      </Field>
    </Form>
  );
}

export default function FnSfr00801Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [lookupId, setLookupId] = useState<number | string>('');
  const [detail, setDetail] = useState<Row | undefined>(undefined);
  const [mode, setMode] = useState<Mode>('');
  const [printText, setPrintText] = useState('');

  const track = (row: Row) => {
    setRows((prev) => [row, ...prev.filter((r) => r.journalEntryId !== row.journalEntryId)]);
  };

  const fetchEntry = async (id: number | string): Promise<Row> => {
    return call('GET', `/journal-entries/${id}`, role);
  };

  const open = async (id: number | string) => {
    try {
      const row = await fetchEntry(id);
      track(row);
      setDetail(row);
      setPrintText('');
    } catch (e) {
      notify(messageOf(e));
    }
  };

  const refreshDetail = async () => {
    if (!detail) {
      return;
    }
    const row = await fetchEntry(detail.journalEntryId as number);
    track(row);
    setDetail(row);
  };

  const print = async () => {
    if (!detail) {
      return;
    }
    try {
      const res = await call('GET', `/journal-entries/${detail.journalEntryId}/print`, role);
      setPrintText(String(res.printFile ?? ''));
    } catch (e) {
      notify(messageOf(e));
    }
  };

  if (detail) {
    const status = String(detail.status);
    const lines = (detail.lines as Row[]) ?? [];
    const editable = status !== '승인' && status !== '마감';
    return (
      <div className="doc">
        <button type="button" className="ghost" onClick={() => setDetail(undefined)}>
          목록으로 돌아가기
        </button>
        <section className="box">
          <h2>전표</h2>
          <Pairs
            items={[
              ['전표 ID', String(detail.journalEntryId)],
              ['전표 일자', <DateText value={detail.entryDate} />],
              ['전표 상태', <Badge value={detail.status} />],
              ['차변 합계', <Num value={detail.totalDebitAmount} />],
              ['대변 합계', <Num value={detail.totalCreditAmount} />],
              ['적요', String(detail.summary ?? '')],
              ['증빙내역', String(detail.evidenceDetail ?? '')],
            ]}
          />
        </section>
        <section className="box">
          <h2>분개 내역</h2>
          <DataTable
            rows={lines}
            empty="분개 내역이 없습니다."
            columns={[
              { key: 'lineNo', label: '순번' },
              { key: 'accountSubjectId', label: '계정과목', render: (r) => <RefName table="account_subject" role={role} value={r.accountSubjectId} /> },
              { key: 'debitAmount', label: '차변 금액', render: (r) => <Num value={r.debitAmount} /> },
              { key: 'creditAmount', label: '대변 금액', render: (r) => <Num value={r.creditAmount} /> },
              { key: 'managementItemValue', label: '관리항목 값' },
            ]}
          />
        </section>
        <section className="box">
          <h2>처리</h2>
          {editable && (
            <button type="button" onClick={() => setMode('edit')}>
              관리항목·적요·증빙내역 수정
            </button>
          )}
          {status === '승인' && (
            <button type="button" className="ghost" onClick={() => setMode('cancel')}>
              승인 해제
            </button>
          )}
          <button type="button" className="ghost" onClick={print}>
            전표 출력
          </button>
        </section>
        {printText !== '' && (
          <section className="box">
            <h2>전표 출력물</h2>
            <pre>{printText}</pre>
          </section>
        )}
        {mode === 'edit' && (
          <Drawer title="전표 수정" onClose={() => setMode('')}>
            <EditForm
              role={role}
              detail={detail}
              onDone={async () => {
                setMode('');
                notify('전표를 수정했습니다.');
                await refreshDetail();
              }}
            />
          </Drawer>
        )}
        {mode === 'cancel' && (
          <Drawer title="승인 해제" onClose={() => setMode('')}>
            <CancelForm
              role={role}
              detail={detail}
              onDone={async () => {
                setMode('');
                notify('승인을 해제했습니다.');
                await refreshDetail();
              }}
            />
          </Drawer>
        )}
      </div>
    );
  }

  return (
    <div className="doc">
      <h1>전표 입력·관리</h1>
      <Filters
        onSearch={() => {
          if (lookupId === '') {
            notify('조회할 전표를 선택하세요.');
            return;
          }
          open(lookupId);
        }}
        onReset={() => setLookupId('')}
      >
        <Field label="전표 ID">
          <LookupSelect table="journal_entry" role={role} value={lookupId} onChange={setLookupId} />
        </Field>
      </Filters>
      <Band total={rows.length}>
        <button type="button" onClick={() => setMode('create')}>
          전표 입력
        </button>
        <button type="button" className="ghost" onClick={() => setMode('bulk')}>
          증빙내역 일괄 변경
        </button>
      </Band>
      <DataTable
        rows={rows}
        onRowClick={(r) => open(r.journalEntryId as number)}
        empty="아직 조회한 전표가 없습니다. 위에서 전표를 선택해 조회하거나 전표를 입력하세요."
        columns={[
          { key: 'journalEntryId', label: '전표 ID' },
          { key: 'entryDate', label: '전표 일자', render: (r) => <DateText value={r.entryDate} /> },
          { key: 'status', label: '전표 상태', render: (r) => <Badge value={r.status} /> },
          { key: 'totalDebitAmount', label: '차변 합계', render: (r) => <Num value={r.totalDebitAmount} /> },
          { key: 'totalCreditAmount', label: '대변 합계', render: (r) => <Num value={r.totalCreditAmount} /> },
        ]}
      />
      {mode === 'create' && (
        <Drawer title="전표 입력" onClose={() => setMode('')}>
          <CreateForm
            role={role}
            onDone={async (id) => {
              setMode('');
              notify('전표를 저장했습니다.');
              await open(id);
            }}
          />
        </Drawer>
      )}
      {mode === 'bulk' && (
        <Drawer title="증빙내역 일괄 변경" onClose={() => setMode('')}>
          <BulkForm
            role={role}
            notify={notify}
            onDone={async (ids) => {
              setMode('');
              notify('증빙내역을 변경했습니다.');
              for (const id of ids) {
                try {
                  track(await fetchEntry(id));
                } catch (e) {
                  notify(messageOf(e));
                }
              }
            }}
          />
        </Drawer>
      )}
    </div>
  );
}
